import requests
from datetime import datetime

def get_weather(city):
    api_key = "YOUR_API_KEY"
    base_url = "http://api.openweathermap.org/data/2.5/weather?"

    complete_url = f"{base_url}appid={api_key}&q={city}"
    response = requests.get(complete_url)
    data = response.json()

    if data["cod"] != "404":
        main = data["main"]
        wind = data["wind"]
        weather_condition = data["weather"][0]["description"].lower()

        return {
            "temperature": main["temp"],
            "humidity": main["humidity"],
            "wind speed": wind["speed"],
            "weather condition": weather_condition,
        }
    else:
        return {"error": "City not found"}

def update_weather(city):
    current_weather = get_weather(city)

    if current_weather["error"] is None:
        print("Current weather in", city, ":")
        for key, value in current_weather.items():
            print(key.capitalize(), "-", value))

        user_input = input("\nEnter 'update' to update the weather information for a different city: ").lower()

        if user_input == "update":
            new_city = input("Enter the name of the city you want to check the weather for: ")
            return update_weather(new_city)
        else:
            print("\nInvalid choice. Exiting..."))
            exit()
    else:
        print("Error:", current_weather["error"]),
        user_input = input("\nEnter 'update' to update the weather information for a different city: ").lower()

